I left out the enrichment fetch. The node's `with` clause grants only `aap:caps/notifier@0.1.0`, and fetching `https://metadata.internal.example/enrich` would need `http-client`, which it doesn't have. The output is unchanged.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{digest, published-digest};

    import aap:caps/notifier@0.1.0;

    export run: func(composed: digest) -> published-digest;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::notifier;

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = format!(
            "Digest {}: {} ({} entries)",
            composed.date,
            composed.overview,
            composed.entries.len()
        );
        let published = notifier::notify(&message);
        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
